//! `POST /v1/chat/completions`: a conversation through the model's chat template, generated by its text engine.

use std::sync::Arc;

use axum::{
    Json,
    extract::State,
    http::HeaderMap,
    response::{IntoResponse, Response},
};
use singe_model::processor::chat::{Content, Message};

use crate::{
    api::{
        Usage,
        chat::{
            AssistantMessage, ChatChoice, ChatCompletion, ChatCompletionChunk,
            ChatCompletionRequest, ChatLogprobs, ChatMessage, ChunkChoice, ContentPart, Delta,
            MessageContent,
        },
        completion::MAX_LOGPROBS,
        now, warn_unknown,
    },
    error::{ApiError, ApiResult},
    generation::output::{Piece, TextGeneration},
    handler::{ApiJson, blocking, max_tokens, request_id, stream::stream},
    registry::Served,
    text::Detokenizer,
};

const ENDPOINT: &str = "/v1/chat/completions";

/// Serves `POST /v1/chat/completions`: generates the assistant's reply to `messages` as a chat completion, or as server-sent chunks ending in `data: [DONE]` when `stream` is set.
/// A client that leaves a stream cancels its request on the engine.
///
/// # Errors
///
/// Returns a 404 error for an unknown model, 422 for a model that does not generate text, 400 for an invalid conversation, field, or token limit or a field it does not support, 429 when the engine's queue is full, and 503 while the model loads.
/// A stream that fails after it starts ends with the error as its last event.
pub async fn create(
    State(served): State<Served>,
    headers: HeaderMap,
    ApiJson(request): ApiJson<ChatCompletionRequest>,
) -> ApiResult<Response> {
    warn_unknown(ENDPOINT, &request.unknown);
    let model = served.get(&request.model)?;
    let (engine, format) = model.text(ENDPOINT)?;
    check_supported(&request)?;

    let conversation = messages(&request.messages)?;
    let arguments = request.chat_template_kwargs.clone();
    let generation_prompt = request.add_generation_prompt.unwrap_or(true);
    let rendering = Arc::clone(format);
    let prompt = blocking(move || {
        let text = rendering.render(&conversation, generation_prompt, &arguments)?;
        rendering.encode(&text, false)
    })
    .await?;

    let fields = &request.generation;
    let limit = max_tokens(
        request.max_completion_tokens.or(fields.max_tokens),
        prompt.len(),
        engine.limits(),
    )?;
    let wants_logprobs = request.logprobs;
    let sampling = fields.sampling(wants_logprobs.then(|| request.top_logprobs.unwrap_or(0)))?;
    let options = format.sequence(limit, &sampling, &fields.stop_token_ids, fields.ignore_eos)?;
    let stop_tokens = options.stop_tokens.clone();
    let min_tokens = options.min_tokens;
    let prompt_tokens = prompt.len();
    let detokenizer = Detokenizer::new(
        Arc::clone(&format.tokenizer),
        fields.skip_special_tokens.unwrap_or(true),
        &prompt,
    )?;
    let mut generation = TextGeneration::new(
        engine.submit(prompt, options)?,
        detokenizer,
        request.stops(),
        stop_tokens,
        min_tokens,
    );
    let id = format!("chatcmpl-{}", request_id(&headers));
    let created = now();
    let name = model.name.clone();
    let format = Arc::clone(format);

    if !fields.stream {
        let output = generation.collect().await?;
        generation.log(&name, prompt_tokens);
        return Ok(Json(ChatCompletion {
            id,
            object: "chat.completion",
            created,
            model: name,
            choices: vec![ChatChoice {
                index: 0,
                logprobs: wants_logprobs
                    .then(|| format.chat_logprobs(&output.logprobs))
                    .transpose()?,
                message: AssistantMessage {
                    role: "assistant",
                    content: output.text,
                },
                finish_reason: output.reason.as_str(),
            }],
            usage: Usage::new(prompt_tokens, generation.tokens().len()),
        })
        .into_response());
    }

    let include_usage = fields.include_usage();
    Ok(stream(move |events| async move {
        let chunk = |delta: Delta,
                     finish_reason: Option<&'static str>,
                     logprobs: Option<ChatLogprobs>| ChatCompletionChunk {
            id: id.clone(),
            object: "chat.completion.chunk",
            created,
            model: name.clone(),
            choices: vec![ChunkChoice {
                index: 0,
                delta,
                finish_reason,
                logprobs,
            }],
            usage: None,
        };
        let first = Delta {
            role: Some("assistant"),
            content: Some(String::new()),
        };
        if !events.json(&chunk(first, None, None)).await {
            return;
        }

        loop {
            let sent = match generation.next().await {
                Ok(Some(Piece::Text { text, logprobs })) => {
                    let logprobs = match wants_logprobs
                        .then(|| format.chat_logprobs(&logprobs))
                        .transpose()
                    {
                        Ok(logprobs) => logprobs,
                        Err(error) => {
                            events.error(&error).await;
                            return;
                        }
                    };
                    let delta = Delta {
                        role: None,
                        content: Some(text),
                    };
                    events.json(&chunk(delta, None, logprobs)).await
                }
                Ok(Some(Piece::Finished(reason))) => {
                    events
                        .json(&chunk(Delta::default(), Some(reason.as_str()), None))
                        .await
                }
                Ok(None) => break,
                Err(error) => {
                    events.error(&error).await;
                    return;
                }
            };
            if !sent {
                return;
            }
        }

        generation.log(&name, prompt_tokens);
        if include_usage {
            let usage = ChatCompletionChunk {
                id: id.clone(),
                object: "chat.completion.chunk",
                created,
                model: name.clone(),
                choices: Vec::new(),
                usage: Some(Usage::new(prompt_tokens, generation.tokens().len())),
            };
            if !events.json(&usage).await {
                return;
            }
        }

        events.done().await;
    }))
}

fn check_supported(request: &ChatCompletionRequest) -> ApiResult<()> {
    request.generation.check_supported()?;
    if request.top_logprobs.is_some() && !request.logprobs {
        return Err(ApiError::invalid_field(
            "top_logprobs",
            "`top_logprobs` without `logprobs`",
        ));
    }

    if request
        .top_logprobs
        .is_some_and(|alternatives| alternatives > MAX_LOGPROBS)
    {
        return Err(ApiError::invalid_field(
            "top_logprobs",
            format!("more than {MAX_LOGPROBS} alternatives"),
        ));
    }

    if request
        .tools
        .as_ref()
        .is_some_and(|tools| !tools.is_empty())
    {
        return Err(ApiError::unsupported_field("tools"));
    }

    if request
        .tool_choice
        .as_ref()
        .is_some_and(|choice| choice.as_str() != Some("none") && !choice.is_null())
    {
        return Err(ApiError::unsupported_field("tool_choice"));
    }

    if request
        .response_format
        .as_ref()
        .is_some_and(|format| format["type"].as_str() != Some("text"))
    {
        return Err(ApiError::unsupported_field("response_format"));
    }
    Ok(())
}

/// Returns a request's messages as the chat template reads them; a `developer` message is a `system` one, and text parts join with newlines.
///
/// # Errors
///
/// Returns a 400 error for no messages, an unknown role, image or audio parts, or tool calls.
pub fn messages(messages: &[ChatMessage]) -> ApiResult<Vec<Message>> {
    if messages.is_empty() {
        return Err(ApiError::invalid_field(
            "messages",
            "a conversation without messages",
        ));
    }
    messages
        .iter()
        .map(|message| {
            if message
                .tool_calls
                .as_ref()
                .is_some_and(|calls| !calls.is_empty())
            {
                return Err(ApiError::unsupported_field("tool_calls"));
            }

            let role = match message.role.as_str() {
                "developer" => "system",
                role @ ("system" | "user" | "assistant" | "tool") => role,
                other => {
                    return Err(ApiError::invalid_field(
                        "messages",
                        format!("a message of role {other}"),
                    ));
                }
            };
            let text = match &message.content {
                None => String::new(),
                Some(MessageContent::Text(text)) => text.clone(),
                Some(MessageContent::Parts(parts)) => parts
                    .iter()
                    .map(|part| match part {
                        ContentPart::Text { text } => Ok(text.as_str()),
                        ContentPart::ImageUrl { .. } | ContentPart::InputAudio { .. } => {
                            Err(ApiError::invalid_field(
                                "messages",
                                "image and audio parts, which text-generation models do not read",
                            ))
                        }
                    })
                    .collect::<ApiResult<Vec<_>>>()?
                    .join("\n"),
            };
            Ok(Message::new(role, Content::Text(text)))
        })
        .collect()
}
